def close(x, ref, rtol: float = 1e-14, atol: float = 0.0) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

