def call(n: str, a: List[float]) -> float:
    if n == 'gamma': return sp.gamma(a[0])
    if n == 'gammaln': return sp.gammaln(a[0])
    if n == 'loggamma': return sp.loggamma(a[0])
    if n == 'digamma': return sp.digamma(a[0])
    if n == 'beta': return sp.beta(a[0], a[1])
    if n == 'betaln': return sp.betaln(a[0], a[1])
    if n == 'betainc': return sp.betainc(a[0], a[1], a[2])
    if n == 'betaincinv': return sp.betaincinv(a[0], a[1], a[2])
    if n == 'gammainc': return sp.gammainc(a[0], a[1])
    if n == 'gammaincc': return sp.gammaincc(a[0], a[1])
    if n == 'gammaincinv': return sp.gammaincinv(a[0], a[1])
    if n == 'erf': return sp.erf(a[0])
    if n == 'erfc': return sp.erfc(a[0])
    if n == 'erfinv': return sp.erfinv(a[0])
    if n == 'erfcinv': return sp.erfcinv(a[0])
    if n == 'ndtr': return sp.ndtr(a[0])
    if n == 'ndtri': return sp.ndtri(a[0])
    if n == 'log_ndtr': return sp.log_ndtr(a[0])
    if n == 'stdtr': return sp.stdtr(a[0], a[1])
    if n == 'stdtrit': return sp.stdtrit(a[0], a[1])
    if n == 'fdtr': return sp.fdtr(a[0], a[1], a[2])
    if n == 'fdtrc': return sp.fdtrc(a[0], a[1], a[2])
    if n == 'chdtr': return sp.chdtr(a[0], a[1])
    if n == 'chdtrc': return sp.chdtrc(a[0], a[1])
    if n == 'xlogy': return sp.xlogy(a[0], a[1])
    if n == 'xlog1py': return sp.xlog1py(a[0], a[1])
    if n == 'entr': return sp.entr(a[0])
    if n == 'expit': return sp.expit(a[0])
    if n == 'logit': return sp.logit(a[0])
    if n == 'i0': return sp.i0(a[0])
    if n == 'i0e': return sp.i0e(a[0])
    if n == 'i1': return sp.i1(a[0])
    if n == 'i1e': return sp.i1e(a[0])
    raise ValueError(n)

@test
def test_scalar_kernels():
    # 1e-13 rel: Cephes polynomial kernels agree to a few ulp; iterative
    # inverses (betaincinv, gammaincinv, stdtrit) converge to <= 1e-14
    ok = True
    for n, a, ref in CASES:
        got = call(n, a)
        if abs(got - ref) > 1e-13 * abs(ref):
            print('FAIL', n, a, got, ref)
            ok = False
    assert ok
    assert np.isnan(sp.gamma(-2.0))
    assert sp.gamma(0.0) == float('inf')
    assert np.isnan(sp.loggamma(-1.5))
test_scalar_kernels()

@test
def test_array_api():
    assert close(sp.gamma(np.array([0.5, 1.5, 2.5])), gamma_arr)
    assert close(sp.betainc(np.array([1.0, 2.0, 3.0]), 2.0, 0.5), betainc_bc)
    assert close(sp.logsumexp([1.0, 2.0, 3.0, -1.0]), lse_1d)
    assert close(sp.logsumexp(np.array([[1.0, 2.0], [3.0, 1000.0]]), axis=1), lse_ax)
    assert close(sp.logsumexp([1.0, 2.0, 3.0], b=[0.5, 1.0, 2.0]), lse_b)
    assert close(sp.softmax(np.array([[1.0, 2.0, 3.0], [0.0, 0.0, 1.0]]), axis=1), smax)
    assert close(sp.log_softmax(np.array([1.0, 2.0, 3.0])), lsmax)
    assert close(sp.comb(10, 3), comb_f)
    assert close(sp.comb(60.0, 25.0), comb_big, 1e-13)
    assert sp.comb(60, 25, exact=True) == 51915437974328292
    assert close(sp.perm(10, 3), perm_f)
    assert close(sp.factorial(10), fact_f)
    assert sp.factorial(20, exact=True) == 2432902008176640000
test_array_api()


